std::filesystem::path HlfSplitter::createOutputDirectory(const std::filesystem::path& inputFile)
{
   std::filesystem::path outputDirectoryPath;

   try
   {
      // Compose the output directory path
      const std::filesystem::path parentPath = std::filesystem::absolute(inputFile).parent_path();
      outputDirectoryPath = parentPath / composeOutputDirectoryName(inputFile);

      static_cast<void>(std::filesystem::create_directory(outputDirectoryPath));
