void HlfInputDescriptionHeaderRecord::decodePayload(BufferReader& reader)
{
   // Read and verify sub-type is correct for this record type
   uint8_t subType{0U};
   reader.read(&subType, sizeof(uint8_t));

   if (subType == static_cast<uint8_t>(getSubType()))
   {
      // Decode header-specific fields
      constexpr size_t originalIpSize = sizeof(m_originalIp);
      constexpr size_t nameSize = sizeof(m_name);
      constexpr size_t descriptionSize = sizeof(m_description);

      uint16_t dataType{0U};

      reader.read(&m_typeId, sizeof(uint16_t));
      reader.read(&dataType, sizeof(uint16_t));
      HlfHeaderRecord::decodeVarLengthShortString<originalIpSize>(reader, m_originalIp);
      reader.read(&m_originalPort, sizeof(uint16_t));
      HlfHeaderRecord::decodeVarLengthLongString<nameSize>(reader, m_name);
      HlfHeaderRecord::decodeVarLengthLongString<descriptionSize>(reader, m_description);

      if (dataType == static_cast<uint16_t>(HlfDataType::AlphaData))
      {
         m_dataType = HlfDataType::AlphaData;
      }
   }
}

void ConversionManager::writeXmlStringsToFile()
{
   // Write XML whilst the writer is running, or once it is stopped clean up any remaining results
   while (m_writerRunning.load() || !m_futureXmlResultsQueue.empty())
   {
      std::string xml;

      {
         std::scoped_lock<std::mutex> lock(m_futureXmlResultsQueueMutex);

         if (!m_futureXmlResultsQueue.empty())
         {
            xml = m_futureXmlResultsQueue.front().get();
            m_futureXmlResultsQueue.pop();
         }
      }

      m_futureXmlResultsNotFull.notify_one();

      if (!xml.empty())
      {
         xmlToFile(xml);
      }
      else
      {
         std::this_thread::sleep_for(std::chrono::milliseconds(WRITER_POLL_INTERVAL_MS));
      }
   }
}

std::shared_ptr<HlfDataRecord> HlfDataRecordXmlDeserializer::deserialize(
   mxml_node_t* const hlfDataRecordNode)
{
   std::shared_ptr<HlfDataRecord> hlfDataRecord = nullptr;

   if (hlfDataRecordNode != nullptr)
   {
      uint16_t streamId = 0;
      uint64_t uptime = 0;

      if (getAttributeValue(hlfDataRecordNode, AT_HLF_RECORD_UPTIME, uptime))
      {
         if (getAttributeValue(hlfDataRecordNode, AT_HLF_RECORD_STREAM_ID, streamId))
         {
            std::shared_ptr<ApiData> apiData
               = ApiDataXmlDeserializer::deserialize(hlfDataRecordNode);

            hlfDataRecord = std::make_shared<HlfDataRecord>(streamId, uptime, apiData);
         }
         else
         {
            throw XmlSerializationException(
               "HlfDataRecordXmlDeserializer: Attribute missing or wrong type: "
               + std::string(AT_HLF_RECORD_STREAM_ID));
         }
      }
      else
      {
         throw XmlSerializationException(
            "HlfDataRecordXmlDeserializer: Attribute missing or wrong type: "
            + std::string(AT_HLF_RECORD_UPTIME));
      }
   }
   else
   {
      throw XmlSerializationException("HlfDataRecordXmlDeserializer: hlfDataRecordNode is NULL ");
   }

   return hlfDataRecord;
}

