private:
   /// @brief Deserializes a CorrectionsCollection<T, T, T, T, T, T> object to a
   /// provided node
   /// @tparam T_SATELLITE_POSITION Of type Status or Polynomial<T, T>
   /// @tparam T_SATELLITE_CLOCK Of type Status or Polynomial<T, T>
   /// @tparam T_PSEUDORANGE_BIAS Of type Status or PseudorangeBias
   /// @tparam T_PHASE_BIAS Of type Status or PhaseBias
   /// @tparam T_PIECEWISE_CONTINUOUS Of type Status or PiecewiseContinuousVariable
   /// @tparam T_PHASE_CENTER Of type Status or PhaseCenter
   /// @param correctionsDataNode to which the CorrectionsCollection<T, T, T, T, T, T> is
   /// deserialized.
   /// @param correctionsCollection CorrectionsCollection<T, T, T, T, T, T> Object to deserialize
   template <
      typename T_SATELLITE_POSITION,
      typename T_SATELLITE_CLOCK,
      typename T_PSEUDORANGE_BIAS,
      typename T_PHASE_BIAS,
      typename T_PIECEWISE_CONTINUOUS,
      typename T_PHASE_CENTER>
   static void deserialize(
      mxml_node_t* correctionsDataNode,
      CorrectionsCollection<
         T_SATELLITE_POSITION,
         T_SATELLITE_CLOCK,
         T_PSEUDORANGE_BIAS,
         T_PHASE_BIAS,
         T_PIECEWISE_CONTINUOUS,
         T_PHASE_CENTER>& correctionsCollection)
   {
      deserializeCorrectionName(correctionsDataNode, correctionsCollection);

      // These can be the respective correction data types or status
      GnssKeyMapXmlDeserializer::deserialize(
         getElementNodeFromPath(correctionsDataNode, EL_SATELLITE_POSITION),
         correctionsCollection.satellitePosition);
      GnssKeyMapXmlDeserializer::deserialize(
         getElementNodeFromPath(correctionsDataNode, EL_SATELLITE_CLOCK),
         correctionsCollection.satelliteClock);
      GnssKeyMapXmlDeserializer::deserialize(
         getElementNodeFromPath(correctionsDataNode, EL_PSEUDO_RANGE_BIAS),
         correctionsCollection.pseudorangeBias);
      GnssKeyMapXmlDeserializer::deserialize(
         getElementNodeFromPath(correctionsDataNode, EL_PHASE_RANGE_BIAS),
         correctionsCollection.phaserangeBias);
      GnssKeyMapXmlDeserializer::deserialize(
         getElementNodeFromPath(correctionsDataNode, EL_SLANT_IONOSPHERE),
         correctionsCollection.slantIonosphere);
      GnssKeyMapXmlDeserializer::deserialize(
         getElementNodeFromPath(correctionsDataNode, EL_SLANT_TROPOSPHERE),
         correctionsCollection.slantTroposphere);
      GnssKeyMapXmlDeserializer::deserialize(
         getElementNodeFromPath(correctionsDataNode, EL_PSEUDO_RANGE_PHASE_CENTER),
         correctionsCollection.pseudorangePhaseCenter);
      GnssKeyMapXmlDeserializer::deserialize(
         getElementNodeFromPath(correctionsDataNode, EL_PHASE_RANGE_PHASE_CENTER),
         correctionsCollection.phaserangePhaseCenter);
   }

