void RuntimeConfig::processOutputFlag(const std::vector<std::string>& optArgs)
{
   if (optArgs.empty())
   {
      PrintHandler::warning(
         "Missing output path, defaulting to " + std::string(DEFAULT_OUTPUT_FOLDER));
      return;
   }

   std::filesystem::path outputPath{optArgs.at(0)};
   s_convert.enabled = true;
   s_version.enabled = false;
   s_help.enabled = false;

   if (outputPath.has_extension())
   {
      if (!s_convert.inputFolderPath.empty())
      {
         PrintHandler::warning(
            "Cannot output folder content to a single file, defaulting to "
            + std::string(DEFAULT_OUTPUT_FOLDER));
         return;
      }

      s_convert.outputFilePath = outputPath.string();
      if (!outputPath.parent_path().empty())
      {
         s_convert.outputFolderPath = outputPath.parent_path().string();
      }
   }
   else
   {
      s_convert.outputFolderPath = outputPath.string();
      s_convert.outputFilePath.clear();
   }
}

