HlfHeaderRecord::HlfString HlfHeaderRecord::initHlfString(const std::string_view src)
{
   HlfString dst;

   if (src.data() == nullptr)
   {
      throw NullPtrException("HlfHeaderRecord");
   }

   if (src.size() + NUL_CHAR_LEN < dst.size())
   {
      // Whole string
      static_cast<void>(src.copy(dst.data(), src.size()));
      dst.at(src.size()) = '\0';
   }
   else
   {
      // Truncate
      static_cast<void>(src.copy(dst.data(), dst.size()));
      dst.back() = '\0';
   }

   return dst;
}

