/// @brief Create measurements and model for coordinates measurements.
      /// @param posMeasurement Position measurement provided by the host.
      /// @return The measurements and model pair.
      static MeasurementsAndModelType createMeasurementsAndModel(
         const std::shared_ptr<const PositionMeasurement>& posMeasurement)
      {
         ModelType coordinatesModel;

         // Transfer the position measurement from the API type to the internal measurement type.
         MeasurementType measurement;
         measurement.value()
            = Map<Coordinates::DIM, 1>(posMeasurement->data.value.data(), Coordinates::DIM);

         // Map flattened upper diagonal array to full symmetric matrix
         auto& covariance = measurement.covariance();
         std::size_t dataIndex = 0;
         for (Index iIdx = 0; iIdx < Coordinates::DIM; ++iIdx)
         {
            for (Index jIdx = iIdx; jIdx < Coordinates::DIM; ++jIdx)
            {
               const double value = posMeasurement->data.covariance.at(dataIndex);
               covariance(iIdx, jIdx) = value;
               covariance(jIdx, iIdx) = value;
               ++dataIndex;
            }
         }

         // Return the constructed MeasurementsAndModel object
         return MeasurementsAndModelType(
            posMeasurement->time,
            {
               {GnssKey(), measurement}
         },
            coordinatesModel);
      }

