bool HlfNormalizer::checkValues(
   const std::vector<std::size_t>& headerSetOffsets,
   const std::vector<HlfStartTimeHeaderRecord>& startTimeHeaders,
   const std::vector<std::size_t>& endUptimeOffsets,
   const bool hasUniqueRecordingId)
{
   bool performNormalization = true;

   if (headerSetOffsets.empty())
   {
      PrintHandler::error("File contains no headers. Normalization cannot be performed.");
      performNormalization = false;
   }

   if (!hasUniqueRecordingId)
   {
      PrintHandler::error(
         "File contains more than one distinct recording ID. Normalization cannot be performed.");
      performNormalization = false;
   }

   if (std::vector<std::size_t> parsedSets{
          headerSetOffsets.size(),
          startTimeHeaders.size(),
          endUptimeOffsets.size()};
       std::any_of(parsedSets.begin(), parsedSets.end(), [&](const auto& val) {
          return val != parsedSets.front();
       }))
   {
      PrintHandler::error("File contains a mismatch in the number of header record types. "
                          "Normalization cannot be performed.");
      performNormalization = false;
   }

   if (headerSetOffsets.size() == 1)
   {
      PrintHandler::success("File contains a single set of headers. No normalization is required.");
      performNormalization = false;
   }

   return performNormalization;
}

