      std::shared_ptr<HlfRecord> record = nullptr;

      {
         std::scoped_lock<std::mutex> lock(m_hlfRecordsMutex);

         if (!m_hlfRecords.empty())
         {
            record = m_hlfRecords.front();
            m_hlfRecords.pop();
         }
      }

      if (record != nullptr)
      {
         BufferWriter writer{m_buffer.data(), m_buffer.size()};
         record->encode(writer);
         m_fileManager.write(m_buffer.data(), writer.getIndex());
      }
      else
      {
         std::this_thread::sleep_for(std::chrono::milliseconds(WRITER_POLL_INTERVAL_MS));
      }
   }
}

