void HlfHeaderRecord::encodeVarLengthShortString(
   BufferWriter& writer,
   const std::string_view shortString)
{
   if (shortString.size() <= std::numeric_limits<uint8_t>::max())
   {
      const uint8_t length{static_cast<uint8_t>(shortString.size())};
      writer.write(&length, sizeof(length));
      writer.write(shortString.data(), length);
   }
   else
   {
      const uint8_t length{0U};
      writer.write(&length, sizeof(length));
   }
}

