SatellitePositions constructSatellitePositions()
{
   struct SatellitePositionData
   {
      Constellation constellation{};
      SatelliteId satelliteId{SatelliteId::ANY_SATELLITE_ID};
      double x{};
      double y{};
      double z{};
   };

   std::pmr::vector<SatellitePositionData> inputSatellitePositions = {
      {Constellation::Gps, SatelliteId{31}, -5269396.8835,  -20630869.8646, 15393632.4152},
      {Constellation::Gps, SatelliteId{2},  -22747055.4530, -13027762.8275, 5848456.9726 },
      {Constellation::Gps, SatelliteId{19}, -10011288.9517, 15243180.4432,  19009340.6137},
      {Constellation::Gps, SatelliteId{25}, 15916423.9421,  -4394961.1486,  20394627.2380},
      {Constellation::Gps, SatelliteId{4},  -24018572.2872, -1916771.3867,  11360928.7956},
      {Constellation::Gps, SatelliteId{32}, 15525856.5628,  -15613234.2643, 14929148.3322},
      {Constellation::Gps, SatelliteId{3},  -13417010.5660, -6057411.1393,  21949454.2705}
   };

   SatellitePositions satellitePositions; // use the default allocator
   satellitePositions.reserve(inputSatellitePositions.size());

   for (const SatellitePositionData& satelliteEntry : inputSatellitePositions)
   {
      GnssKey key = {satelliteEntry.constellation, satelliteEntry.satelliteId, Signal::Any};
      Vector<DIMENSION_3D> position{};
      position = {satelliteEntry.x, satelliteEntry.y, satelliteEntry.z};
      satellitePositions.try_emplace(key, position);
   }

   return satellitePositions;
}

