bool validate(
   const AmbiguityStateWithKeySet& againstCandidate,
   const AmbiguityStateWithKeySet& toValidateCandidate,
   AmbiguityStateWithKeySet& validatedCandidate)
{
   if (toValidateCandidate.empty() || againstCandidate.empty())
   {
      return false;
   }

   static constexpr double SIGNIFICANCE_LEVEL = 0.05;

   using Ambiguities = AmbiguityStateWithKeySet::Ambiguities;
   using Covariance = AmbiguityStateWithKeySet::Covariance;

   auto commonKeySetAndIndices
      = getCommonKeySetAndIndices(toValidateCandidate.keySet(), againstCandidate.keySet());

   if (commonKeySetAndIndices.commonKeySet.empty())
   {
      return false;
   }

   const auto& toValidateIndices = commonKeySetAndIndices.keySet1Indices;
   const auto& againstIndices = commonKeySetAndIndices.keySet2Indices;

   Ambiguities projectedToValidateValues = toValidateCandidate.values()(toValidateIndices);
   const Ambiguities projectedAgainstValues = againstCandidate.values()(againstIndices);

   Covariance projectedToValidateCovariance
      = toValidateCandidate.covariance()(toValidateIndices, toValidateIndices);
   const Covariance projectedAgainstCovariance
      = againstCandidate.covariance()(againstIndices, againstIndices);

   // Test if `a_0' and `a_1' are compatible under BOTH covariances,
   // i.e., Mahalanobis distance: `(a_0 - a_1)^T * inv(Sigma_i) * (a_0 - a_1) <= chi^2_m(1 - alpha)'
   // for i = 0, 1.
   const auto delta = projectedToValidateValues - projectedAgainstValues;

   if (const auto threshold
       = computeChiSquareThreshold(SIGNIFICANCE_LEVEL, static_cast<std::size_t>(delta.size()));
       !chiSquareTest(delta, projectedToValidateCovariance, threshold)  // Sigma_0
       || !chiSquareTest(delta, projectedAgainstCovariance, threshold)) // Sigma_1
   {
      return false;
   }

   // toValidateCandidate's values projected onto common key set.
   validatedCandidate = AmbiguityStateWithKeySet{
      std::move(projectedToValidateValues),
      std::move(projectedToValidateCovariance),
      std::move(commonKeySetAndIndices.commonKeySet)};

   return true;
}

