   /// object
   /// @tparam DEGREE Number of degrees of the Polynomial
   /// @tparam DIMENSION Number of dimensions of the Polynomial
   /// @param mapValueNode Keymap item XML Node to read from
   /// @param polynomial Polynomial<DEGREE, DIMENSION> object to deserialize to
   template <unsigned int DEGREE, unsigned int DIMENSION>
   static void
   deserializeMapValue(mxml_node_t* const mapValueNode, Polynomial<DEGREE, DIMENSION>& polynomial)
   {
      mxml_node_t* childNode = getElementNodeFromPath(mapValueNode, EL_POLYNOMIAL);

      if (childNode != nullptr)
