            "GnssKeyMapXmlDeserializer: Element cannot be found: " + std::string(EL_POLYNOMIAL));
      }
   }

/// @brief Check if lhs is less than rhs within epsilon tolerance
/// @param epsilon Tolerance for comparison (uses default if negative)
inline bool compareLess(const Time& lhs, const Time& rhs, double epsilon = -1.0)
{
   if (epsilon < 0)
   {
      epsilon = TIME_COMPARISON_EPSILON;
   }
   return (lhs - rhs).value < -epsilon;
}

public:
   //-----------------------------------------------------------------------
   //! @brief Create the ThreadBase object
   //
   // @param instanceId The instance ID of the positioning engine
   // @param threadName The name of the thread
   //-----------------------------------------------------------------------
   ThreadBase(const uint16_t instanceId, const std::string_view threadName)
      : m_instanceId(instanceId)
   {
      const auto copyChars
         = std::min(threadName.length(), m_threadName.size() - Logger::NULL_TERMINATOR_LEN);
      // Copy the characters
      auto* endIt = std::copy_n(threadName.begin(), copyChars, m_threadName.data());

      // Null-terminate
      *endIt = '\0';
   }

/// @brief Create update measurements and models.
   /// @param gnssMeasurements The GNSS measurements.
   /// @param positionMeasurement A position measurement if available.
   /// @param velocityMeasurement A velocity measurement if available.
   /// @param satellitePositions The current satellite positions.
   /// @return The update measurements and models.
   static UpdateMeasurements createUpdateMeasurements(
      const GnssMeasurements& gnssMeasurements,
      const std::shared_ptr<const PositionMeasurement>& positionMeasurement,
      [[maybe_unused]] const std::shared_ptr<const VelocityMeasurement>& velocityMeasurement,
      const SatellitePositions& satellitePositions,
      const GnssKeyMap<StochasticState<Ionosphere>>& ionoMeasurements)
   {
      // Initialize UpdateMeasurements.
      UpdateMeasurements updateMeasurements;

      if (!gnssMeasurements.data.pseudorangeMeasurements.empty())
      {
         // Create a PseudorangeMeasurementModel with the current satellite positions.
         auto psrMeasurementAndModel = PseudorangeMeasurementPolicy::createMeasurementsAndModel(
            gnssMeasurements.time,
            satellitePositions,
            gnssMeasurements.data.pseudorangeMeasurements);

         updateMeasurements.emplace_back(std::move(psrMeasurementAndModel));
      }

      if (!gnssMeasurements.data.phaserangeMeasurements.empty())
      {
         auto phrMeasurementAndModel = PhaserangeMeasurementPolicy::createMeasurementsAndModel(
            gnssMeasurements.time,
            satellitePositions,
            gnssMeasurements.data.phaserangeMeasurements);

         updateMeasurements.emplace_back(std::move(phrMeasurementAndModel));
      }

      if (positionMeasurement)
      {
         auto coordsMeasurementAndModel
            = CoordinatesMeasurementPolicy::createMeasurementsAndModel(positionMeasurement);

         updateMeasurements.emplace_back(std::move(coordsMeasurementAndModel));
      }

      if (!satellitePositions.empty())
      {
         auto ionoMeasurementAndModel = IonosphereMeasurementPolicy::createMeasurementsAndModel(
            gnssMeasurements.time,
            satellitePositions,
            ionoMeasurements);

         updateMeasurements.emplace_back(std::move(ionoMeasurementAndModel));
      }

      return updateMeasurements;
   }

Constellation GnssKeyXmlDeserializer::stringToConstellation(const std::string& str)
{
   static const std::unordered_map<std::string_view, Constellation> CONSTELLATION_MAP = {
      {"Any",     Constellation::Any    },
      {"Gps",     Constellation::Gps    },
      {"Glonass", Constellation::Glonass},
      {"Galileo", Constellation::Galileo},
      {"Beidou",  Constellation::Beidou },
      {"Navic",   Constellation::Navic  }
   };

   const auto iter = CONSTELLATION_MAP.find(str);

   if (iter == CONSTELLATION_MAP.end())
   {
      throw XmlSerializationException(
         "GnssKeyXmlDeserializer: Unrecognised Constellation  attribute value: " + str);
   }

   return iter->second;
}

