std::optional<ReconstructionTraits<PositionReconstruction>::AbsoluteData>
PositionReconstruction::reconstructFromLast()
{
   if (!m_lastReconstructedPosition.has_value())
   {
      return std::nullopt;
   }
   const auto& lastPos = (*m_lastReconstructedPosition).value;

   auto containingIt = findIncrementAtTime(lastPos.time, m_positionIncrements);
   if (containingIt == m_positionIncrements.end())
   {
      return std::nullopt;
   }

   EigenPosition result;
   result.time = lastPos.time;
   result.data = lastPos.data;

   const auto alpha = calculateInterpolationFactor((*containingIt).value, lastPos.time);
   if (!alpha.has_value())
   {
      return std::nullopt;
   }
   applyInterpolatedIncrement(*alpha, (*containingIt).value, result);

   const bool isNoGaps
      = accumulateSubsequentIncrements(std::next(containingIt), m_positionIncrements, result);

   if (!isNoGaps)
   {
      return std::nullopt;
   }
   return ReconstructionTraits<PositionReconstruction>::AbsoluteData(
      result,
      (*m_lastReconstructedPosition).metaData);
}

