// POSIX sockets C API takes `sockaddr*`. Confine the reinterpret_cast to a single helper
// so call sites read naturally and the suppression lives in one place only.
// The parameter cannot be const: `getpeername` writes the peer address through the
// returned pointer, so casting away const here would be undefined behaviour.
sockaddr* asSockAddr(sockaddr_in* addr) noexcept 
{

   return reinterpret_cast<sockaddr*>(addr); 
}

//!  Description : Method performing an in-place modified Cholesky factorization of the square matrix *this without pivoting.
//!                Note that only the lower triangular part of *this is accessed and modified.
//!                If the method returns Eigen::Success, then the unit lower triangular part of *this contains the 
//!                matrix elements of L and the diagonal entries of *this the diagonal elements of the matrix D. 
//!                In all other cases, the decomposition is not usable and the lower triangular part of *this has possibly been destroyed.
//!
//!  Results     : Success - in case of no errors. 
//!                InvalidInput - if *this is not a square matrix.
//!                NumericalIssue - if *this is not positive definite and/or nearly singular.
//
ComputationInfo computeLdFactorizationInPlace()
{
    if( !(this->isSquare()) )
    {
        return InvalidInput;
    }

    const Index cDim = (*this).derived().rows();

    if(cDim <= 1)
    {
        // if cDim == 0 or cDim == 1 there is nothing to do
        return Success;
    }

    for( Index idxCol=0; idxCol<cDim; ++idxCol )
    {
        if( (*this).derived()(idxCol, idxCol) < std::numeric_limits<Scalar>::min() )
        {
            return NumericalIssue;
        }
        const Scalar cAlpha = Scalar(1)/(*this).derived()(idxCol, idxCol);
        for( Index idxCol2=cDim-1; idxCol2>idxCol; --idxCol2 )
        {
            const Scalar cBeta = (*this).derived()(idxCol2, idxCol);
            (*this).derived()(idxCol2, idxCol) *= cAlpha;
            (*this).derived().col(idxCol2).tail(cDim-idxCol2).noalias() -= cBeta * (*this).derived().col(idxCol).tail(cDim-idxCol2);
        }
    }
    return Success;
}

void HlfRecord::decodeGenericRecord(BufferReader& reader, uint32_t& payloadLength)
{
   std::array<char, PREAMBLE.size()> preamble{};
   uint32_t initialCrc{0U};

   // Start reading from start of buffer
   reader.setIndex(0U);

   // Read initial fields
   reader.read(preamble.data(), preamble.size());
   reader.read(&m_recordType, sizeof(uint16_t));
   reader.read(&payloadLength, sizeof(uint32_t));
   reader.read(&initialCrc, sizeof(uint32_t));
}

