std::filesystem::path
deriveOutputFilePath(const std::string& inputFilePath, const std::string& outputFolderPath)
{
   namespace fs = std::filesystem;

   if (inputFilePath.empty())
   {
      throw FileException("Input file path is empty when deriving output file path");
   }

   fs::path inputPath{inputFilePath};
   std::string extension = inputPath.extension().string();

   // Normalize the extension to lower-case to ensure case-insensitive comparison.
   static_cast<void>(
      std::transform(extension.begin(), extension.end(), extension.begin(), [](const char chr) {
         return std::tolower(chr, std::locale::classic());
      }));

   // Determine the base output folder (user-provided or default).
   fs::path outputFolder{outputFolderPath.empty() ? DEFAULT_OUTPUT_FOLDER : outputFolderPath};

   fs::path destSubFolder;
   fs::path destPath;

   if (extension == XML_EXTENSION)
   {
      // Converting XML -> HLF.  Place the result under the ".hlf" sub-folder.
      destSubFolder = HLF; // ".hlf"
      destPath = outputFolder / destSubFolder / inputPath.stem();
      destPath.replace_extension(HLF_EXTENSION);
   }
   else if (extension == HLF_EXTENSION)
   {
      // Converting HLF -> XML.  Place the result under the ".xml" sub-folder.
      destSubFolder = XML; // ".xml"
      destPath = outputFolder / destSubFolder / inputPath.stem();
      destPath.replace_extension(XML_EXTENSION);
   }
   else
   {
      throw FileException("Unsupported input file extension: " + extension);
   }

   // Ensure the destination directory exists.
   try
   {
      if (!fs::exists(destPath.parent_path()))
      {
         fs::create_directories(destPath.parent_path());
      }
   }
   catch (const std::exception& ex)
   {
      throw FileException(std::string{"Failed to create output directories: "} + ex.what());
   }

   return destPath;
}

/// @brief Handle the insertion of data as a primary data type.
   ///
   /// @param iterator The iterator pointing to the first package that corresponds to a time-stamp
   ///                 that is not larger than the given time.
   /// @param time     The time-stamp of the data to be inserted.
   /// @param source   The source ID of the data to be inserted.
   ///
   /// @return An iterator pointing to the package in which the data can be inserted, or end() if no
   ///         such package exists.
   Iterator handleAsPrimary(const Iterator& iterator, const Time& time, const SourceId& source)
   {
      // Check that the assembly line is configured for the assigned sourceId.
      if ((!m_primaryPeriod) || (source.value != m_primaryPeriod->sourceId.value))
      {
         Logger::error(
            FacilityCode::Synchronizer,
            "The engine is not configured for the stream with source ID: {}",
            source.value);
         return m_packages.end();
      }

      // Check if we have a minimum delay set for the next packages --> we are predicting on a
      // regular basis now --> check that we meet the minimum time for creating this package.

      if (m_minNextPubTime && compareLess(time, (*m_minNextPubTime)))
      {
         // If the time is less than the minimum time for creating a package, we cannot insert
         // data into it as we do not expect matching at this time-stamp.
         return m_packages.end();
      }

      // Check whether we are within the maximum time for creating a package.
      if ((m_minNextPubTime && m_maxNextPubTime) && compareLess((*m_maxNextPubTime), time))
      {
         // If the time is greater than the maximum time for creating a package, we need to
         // increment by the package creation period.
         Time newMaxTime
            = incrementTimePastThreshold(time, (*m_maxNextPubTime), m_packageCreatePeriod);

         // This is the new interval for the next package creation.
         (*m_minNextPubTime) += (newMaxTime - (*m_maxNextPubTime));
         (*m_maxNextPubTime) = newMaxTime;

         // In case there was an outage of the primary data-link and no new controls were provided
         // by the host (expected periods), or a reset, check that this data-point falls under a
         // valid future interval for package creation.
         if (compareLess(time, (*m_minNextPubTime)))
         {
            return m_packages.end();
         }
      }

      // We did not find a first package that is not less than the given time, we need to
      // create a new one.
      if (iterator == m_packages.end())
      {
         Package newPackage;
         newPackage.setTime(time);
         pushBackInSizedDeque(DEQUE_MAX_SIZE, newPackage, m_packages);

         return std::prev(m_packages.end());
      }

      // The current iterator points to the first package that is not less than the time,
      // so it must be the one we want to insert data into -- this would be the case if we
      // have multiple primary sources and two of their datapoints coincide.
      return compareEqual(iterator->getTime(), time) ? iterator : m_packages.end();
   }

