/// @brief Adjusts GNSS key for state map entries, controlling state vector/matrix dimensions.
   /// @details Groups by constellation and signal; standardizes satellite ID for signal-specific
   /// biases.
   /// @param key The original GNSS key to be sanitized.
   /// @return A sanitized GNSS key with constellation and signal preserved, satellite ID
   /// standardized.
   static GnssKey sanitizedStateKeySetKey(const GnssKey& key)
   {
      return {key.constellation, SatelliteId{SatelliteId::ANY_SATELLITE_ID}, key.signal};
   }

private:
   bool dispatchResetAndWait(ResetAction reset)
   {
      bool result{true};

      m_resetCompleteCount = 0;

      // Dispatch reset action to all workers
      std::apply(
         [&](auto&... worker) {
            (..., ([&](auto& currentWorker) {
                currentWorker.clearQueue();
                result &= currentWorker.pushEvent(reset);
             }(worker)));
         },
         m_workers);

      if (!result)
      {
         // One or more workers failed to accept event in its queue
         Logger::critical(FacilityCode::Initialization, "Reset: Failed sending event to worker.");
         return false;
      }

      // Wait for all workers to signal completion of the action
      std::unique_lock<std::mutex> lock(m_resetResponseMutex);
      result = m_resetActionCv.wait_for(lock, RESET_TIMEOUT, [&] {
         return m_resetCompleteCount >= WORKER_COUNT;
      });

      if (!result)
      {
         Logger::critical(FacilityCode::Initialization, "Reset: Timeout.");
      }

      return result;
   }

/// @brief Find a package with an epoch time that matches exactly with the one attached to a
   ///        data-point.
   ///
   /// @param iterator The iterator pointing to the first package that corresponds to a time-stamp
   ///                 that is not less than the data time-stamp.
   /// @param time     The time-stamp of the data to be inserted.
   ///
   /// @return An iterator pointing to the package in which the data can be inserted, or end() if we
   ///         cannot match based on this time requirement.
   ///
   Iterator handleAsOnTime(const Iterator& iterator, const Time& time)
   {
      // If the iterator points to a package with the same time, we can insert data into it.
      return (iterator != m_packages.end() && compareEqual(iterator->getTime(), time))
              ? iterator
              : m_packages.end();
   }

