   if (Deserializer::deserializeBool(reader))
   {
      StochasticVariableDeserializer::deserialize(reader, solutionPVData.position.emplace());
   }
   else
   {
      solutionPVData.position = std::nullopt;
   }

   if (Deserializer::deserializeBool(reader))
   {
      StochasticVariableDeserializer::deserialize(reader, solutionPVData.velocity.emplace());
   }
   else
   {
      solutionPVData.velocity = std::nullopt;
   }
}

