void HlfNormalizer::writeNormalizedFile(
   std::ifstream& inputFile,
   std::size_t bytesToWrite,
   const std::filesystem::path& normalizedFilePath,
   const std::optional<const uint64_t> endUptime,
   const std::size_t offset)
{
   const std::filesystem::path tempFilePath = normalizedFilePath.string() + TMP_EXTENSION;

   std::ofstream normalizedFile;
   static constexpr auto EXCEPTIONS_MODE = std::ifstream::badbit;
   normalizedFile.exceptions(EXCEPTIONS_MODE);

   try
   {
      normalizedFile.open(tempFilePath, std::ios::binary);

      const uint32_t outBufferSize = 128U * 1024U;
      std::vector<char> outBuffer(outBufferSize);

      // Write the data to the file
      while (bytesToWrite > 0)
      {
         const std::size_t bytesToRead
            = (bytesToWrite > outBufferSize) ? outBufferSize : bytesToWrite;

         static_cast<void>(
            inputFile.read(outBuffer.data(), static_cast<std::streamsize>(bytesToRead)));
         static_cast<void>(
            normalizedFile.write(outBuffer.data(), static_cast<std::streamsize>(bytesToRead)));

         bytesToWrite -= bytesToRead;
      }

      if (endUptime.has_value())
      {
         writeEndUptime(normalizedFile, endUptime.value(), offset);
      }

      normalizedFile.close();

      std::filesystem::rename(tempFilePath, normalizedFilePath);
   }
   catch (const std::exception& ex)
   {
      throw FileException("Failed to write file: " + std::string(ex.what()));
   }
}

