constexpr std::uint32_t Crc32::reflect(std::uint32_t data, const std::uint8_t nBits) noexcept
{
   std::uint32_t reflection = 0U;

   for (std::uint8_t bit = 0U; bit < nBits; ++bit)
   {
      if ((data & ONE) != ZERO)
      {
         reflection |= (ONE << (nBits - ONE - bit));
      }
      data >>= ONE;
   }

   return reflection;
}

