double calculateMslmMapping(const double elevationAngleRadians)
{
   // Reference: Schaer, S. Mapping and Predicting the Earth's Ionosphere Using the Global
   // Positioning System. Ph.D. Thesis, University of Berne, Bern, Switzerland, 1999.
   const double zenithAngle = bmc::half_pi<double>() - elevationAngleRadians;
   constexpr double radiusRatio = (6371e3 / (6371e3 + 506.7e3));
   constexpr double alpha = 0.9782;
   return 1.0 / std::sqrt(1.0 - square(radiusRatio * std::sin(alpha * zenithAngle)));
}

// check for existence of expected pattern in captured logs
   bool checkLogPattern(
      uint16_t expectedInstanceId,
      const std::string& expectedThreadName,
      const std::string& expectedLogLevel,
      const FacilityCode expectedFacilityCode,
      const std::string& expectedMessage) const
   {
      const auto expectedFacility = static_cast<uint16_t>(expectedFacilityCode);

      std::ostringstream patternStream;

      // Format regular expression to match log string based on the given parameters
      patternStream << R"(\d+,)"          // Matches timestamp and comma
                    << expectedInstanceId // Instance ID
                    << R"(,)"             // Comma separator
                    << expectedThreadName // Thread Name
                    << R"(,)"             // Comma separator
                    << expectedLogLevel   // Log Level (string)
                    << R"(,)"             // Comma separator
                    << expectedFacility   // Facility (uint16_t)
                    << R"(,)"             // Comma separator
                    << expectedMessage;   // The actual message

      const std::regex regxpr(patternStream.str());

      // Check for matching log message and that size parameter matches the actual log message
      // length
      const bool isMatching = std::any_of(
         std::cbegin(m_capturedLogs),
         std::cend(m_capturedLogs),
         [&](const LogCallbackParams& log) {
            return std::regex_search(log.data, regxpr) && (log.data.size() == log.size);
         });

      return isMatching;
   }

