void HlfHeaderRecord::encodeIso8601(BufferWriter& writer, time_t const timestamp)
{
   tm tmBuf{};
   HlfTimeUtil::gmtime(timestamp, &tmBuf);

   // ISO 8601 UTC format, exactly 20 characters: YYYY-MM-DDThh:mm:ssZ
   HlfTimeUtil::IsoTime isoTime{};
   static_cast<void>(strftime(isoTime.data(), isoTime.size(), "%FT%TZ", &tmBuf));

   writer.write(isoTime.data(), HlfTimeUtil::ISO_TIME_LEN);
}

/// @brief Synchronize the package period based on the expected periods of other streams.
   ///
   /// @param otherStreamExpectedPeriod Expected period of another stream to synchronize with.
   /// @param minExpectedPeriod Minimum expected period to consider for synchronization.
   ///
   void synchronizePackagePeriod(
      std::optional<double> otherStreamExpectedPeriod,
      std::optional<double> minExpectedPeriod)
   {
      // Check if the primary period is set.
      if (!m_primaryPeriod)
      {
         // If the primary period is not set, we cannot synchronize the package period.
         return;
      }

      // Set the package creation period (expected period of the package) to the least common
      // multiple of the expected periods.
      m_packageCreatePeriod = std::lcm(
         static_cast<int>(m_primaryPeriod->data.expected * SECONDS_TO_USECS),
         static_cast<int>(
            otherStreamExpectedPeriod.value_or(DEFAULT_EXPECTED_PERIOD) * SECONDS_TO_USECS));
      // Convert back to seconds.
      m_packageCreatePeriod *= USECS_TO_SECONDS;

      // Determine the minimum interval around the expected package creation period that we will
      // create packages -- choose the tightest interval as the package creation interval, which
      // would be the case when we have multiple streams set as mandatory with OnTimeToPrimary
      // matching.
      if (minExpectedPeriod && otherStreamExpectedPeriod)
      {
         m_createPackageHalfInterval = std::min(
            m_createPackageHalfInterval,
            (*otherStreamExpectedPeriod) - (*minExpectedPeriod));
      }
   }

private:
   Iterator eraseSanitizedKey(const GnssKey& key)
   {
      auto itr = m_indexMap.find(key);
      if (itr == m_indexMap.end())
      {
         return m_keySet.end();
      }

      auto selectedIdx = itr->second;
      auto lastIdx = m_keySet.size() - 1;

      if (selectedIdx != lastIdx)
      {
         // Swap with last element
         std::swap(m_keySet[selectedIdx], m_keySet[lastIdx]);
         // Update index map of last element for swapped element
         m_indexMap[m_keySet[selectedIdx]] = selectedIdx;
      }

      // Remove the key from map and vector
      m_indexMap.erase(itr);
      m_keySet.pop_back();

      // Return iterator to the element that was swapped in, or end if erased last
      if (selectedIdx < m_keySet.size())
      {
         return m_keySet.begin() + static_cast<Index>(selectedIdx);
      }

      return m_keySet.end();
   }

