time_t HlfTimeUtil::iso8601ToTimeT(const IsoTime& isoTime)
{
   constexpr int yearOffset{1900};
   constexpr int monthOffset{1};

   tm tmBuf{};

   static_cast<void>(sscanf(
      isoTime.data(),
      "%d-%d-%dT%d:%d:%dZ",
      &tmBuf.tm_year,
      &tmBuf.tm_mon,
      &tmBuf.tm_mday,
      &tmBuf.tm_hour,
      &tmBuf.tm_min,
      &tmBuf.tm_sec));

   tmBuf.tm_year -= yearOffset; // Years since 1900
   tmBuf.tm_mon -= monthOffset; // Months 0-11
   tmBuf.tm_isdst = 0;          // Do not adjust for daylight savings

   // GHS (now no longer supported) has no support for timegm or equivalent function, so we use
   // mktime and adjust.
   return mktime(&tmBuf) + HlfTimeUtil::getTimeZoneOffset();
}

