   ApiData::serialize(writer);

   writer.write(&m_api, sizeof(uint16_t));

   const int32_t errorCode{static_cast<int32_t>(m_errorCode)};
   writer.write(&errorCode, sizeof(int32_t));
}

void RuntimeConfig::processNormalizeFlag(const std::vector<std::string>& optArgs)
{
   if (optArgs.empty())
   {
      throw InvalidArgumentsException("No file provided for --normalize/-n flag");
   }

   const std::filesystem::path hlfFile{optArgs.at(0)};

   if (!hlfFile.has_extension() || (hlfFile.extension().string() != HLF_EXTENSION))
   {
      throw InvalidArgumentsException(
         "Unrecognized input file extension: " + hlfFile.extension().string());
   }

   if (!std::filesystem::exists(hlfFile))
   {
      throw InvalidArgumentsException("Input file does not exist: " + hlfFile.string());
   }

   s_normalizer.inputFile = hlfFile;

   s_convert.enabled = false;
   s_version.enabled = false;
   s_help.enabled = false;
   s_commandFlag = NORMALIZE_FLAG;
}

/// @brief Copies C-style command-line arguments into a std::vector<std::string>.
///
/// Centralises the pointer arithmetic required to iterate a raw argv array so
/// that call sites do not need to suppress cppcoreguidelines-pro-bounds-pointer-arithmetic.
/// Caller is responsible for validating @p argv is non-null before invocation.
///
/// @param argc   Number of elements in @p argv.
/// @param argv   Pointer to an array of @p argc C-strings.
/// @param offset Optional number of leading elements to skip (e.g. 1 to drop the program name).
/// @return A std::vector<std::string> containing argv[offset..argc).
///
inline std::vector<std::string>
argvToVector(const std::size_t argc, const char* const* const argv, const std::size_t offset = 0U)
{
   // Caller-verified: offset <= argc

   return std::vector<std::string>{argv + offset, argv + argc};
}

void MockFileWriter::write(const uint8_t* data, uint32_t size)
{
   if (!m_isOpen)
   {
      throw FileException("Mock file writer is not open");
   }
   // Iterator range over byte buffer

   m_writtenData.insert(m_writtenData.end(), data, data + size);
}

/// @brief Shifts bytes within a single byte buffer towards the front.
///
/// Equivalent to `std::memmove(buffer, buffer + srcOffset, size)`. Centralises
/// the clang-tidy suppressions required by this idiom on raw byte buffers
/// (`cppcoreguidelines-pro-bounds-pointer-arithmetic` for the source offset
/// pointer arithmetic, `bugprone-not-null-terminated-result` for the memmove
/// call) into a single named operation, so call sites do not have to suppress
/// either rule.
///
/// @param buffer    Pointer to a contiguous byte buffer of at least
///                  @p srcOffset + @p size bytes.
/// @param srcOffset Index of the first source byte to shift.
/// @param size      Number of bytes to shift.
///
inline void
shiftBytesToFront(uint8_t* const buffer, const std::size_t srcOffset, const std::size_t size)
{
   // Pointer arithmetic safe by caller-validated bounds precondition.

   static_cast<void>(std::memmove(buffer, buffer + srcOffset, size));
}

std::string MockFileWriter::writtenDataAsString() const
{
   // byte-to-char buffer interop

   return {reinterpret_cast<const char*>(m_writtenData.data()), m_writtenData.size()};
}

/// @brief Writes a byte buffer to a char-oriented output stream.
///
/// Centralises the byte/char reinterpret_cast required by std::ostream's
/// char* API so that call sites can deal in uint8_t buffers without
/// sprinkling reinterpret_cast or NOLINT suppressions.
///
/// @param stream Output stream to write into.
/// @param data   Pointer to byte buffer to write.
/// @param size   Number of bytes to write.
///
inline void writeBytes(std::ostream& stream, const uint8_t* const data, const std::size_t size)
{
   // std::ostream::write only accepts char*, but our buffers are uint8_t. Casting
   // between them is safe: the C++ standard lets you view any object as a sequence
   // of bytes (char, unsigned char, or std::byte), and uint8_t is just unsigned
   // char on every platform we support. This helper keeps the cast (and its


   stream.write(reinterpret_cast<const char*>(data), static_cast<std::streamsize>(size));
}

void MockFileWriter::write(const char* data, uint32_t size)
{

   write(reinterpret_cast<const uint8_t*>(data), size);
}

// checks that vector contains a one of each variants of engine (checks size and uniqueness)
bool isUniqueFullVariantSet(const std::vector<Alpha::Replay::EngineFactory::EngineVariant>& vec)
{
   // clang-tidy false positive on constexpr with variant_size_v

   constexpr std::size_t numTypes
      = std::variant_size_v<Alpha::Replay::EngineFactory::EngineVariant>;

   if (vec.size() != numTypes)
   {
      return false; // Must be exactly one of each type
   }

   std::unordered_set<std::type_index> seen;

   for (const auto& variant : vec)
   {
      std::type_index type = std::visit(
         [](auto&& value) {
            return std::type_index(typeid(value));
         },
         variant);

      if (!seen.insert(type).second)
      {
         return false; // Duplicate type found
      }
   }

   return seen.size() == numTypes;
}

/// @brief Reads from a char-oriented input stream into a byte buffer.
///
/// Companion to writeBytes(). Centralises the byte/char reinterpret_cast
/// required by std::istream's char* API.
///
/// @param stream Input stream to read from.
/// @param data   Pointer to byte buffer to read into.
/// @param size   Maximum number of bytes to read.
/// @return The number of bytes actually read (see std::istream::gcount()).
///
inline std::streamsize readBytes(std::istream& stream, uint8_t* const data, const std::size_t size)
{
   // std::istream::read only accepts char*, but our buffers are uint8_t. Casting
   // between them is safe: the C++ standard lets you view any object as a sequence
   // of bytes (char, unsigned char, or std::byte), and uint8_t is just unsigned
   // char on every platform we support. This helper keeps the cast (and its


   stream.read(reinterpret_cast<char*>(data), static_cast<std::streamsize>(size));
   return stream.gcount();
}

/// @brief Reads from a char-oriented input stream into a byte buffer at the
/// given offset.
///
/// Convenience overload that centralises the offset pointer arithmetic for
/// callers that need to fill the tail of a pre-allocated contiguous buffer.
///
/// @param stream Input stream to read from.
/// @param data   Pointer to a contiguous byte buffer of at least
///               @p offset + @p size bytes.
/// @param offset Index at which to start writing within the buffer.
/// @param size   Maximum number of bytes to read.
/// @return The number of bytes actually read (see std::istream::gcount()).
///
inline std::streamsize readBytes(
   std::istream& stream,
   uint8_t* const data,
   const std::size_t offset,
   const std::size_t size)
{
   // Pointer arithmetic safe by caller-validated bounds precondition.

   return readBytes(stream, data + offset, size);
}
